          '{clone_addr:$clone_addr, repo_name:$repo_name, repo_owner:$repo_owner, mirror:true, mirror_interval:$mirror_interval, private:$private, service:"github"} + $auth')
        # Was `&& echo " OK" || echo " FAIL"` — which printed FAIL and exited 0.
